    Based on the values of f at lo and hi.
    Assert that f(lo) != f(hi).
    """
def bisect(f: Any, lo: Any = 0, hi: Any = None, eps: Any = 1e-09) -> object {
    lo_bool = f(lo);
    if (hi is None) {
        offset = 1;
        while (f((lo + offset)) == lo_bool) {
            offset *= 2;
        }
        hi = lo + offset;
    } else {
        assert (f(hi) != lo_bool);
    }
    while ((hi - lo) > eps) {
        mid = (hi + lo) / 2;
        if (f(mid) == lo_bool) {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    if lo_bool {
        return lo;
    } else {
        return hi;
    }
}

